import numpy as np

def clip_by_norm(g, max_norm):
    """Rescale gradient g so its L2 norm is at most max_norm (direction preserved)."""
    norm = np.linalg.norm(g)
    return g if norm <= max_norm else g * (max_norm / norm)

def clip_by_value(g, m):
    """Clamp every component to [-m, m]."""
    return np.clip(g, -m, m)

