import numpy as np

def softmax(z):
    z = z - np.max(z, axis=-1, keepdims=True)      # shift: largest exponent becomes 0
    e = np.exp(z)
    return e / e.sum(axis=-1, keepdims=True)

def log_softmax(z):
    z = z - np.max(z, axis=-1, keepdims=True)
    return z - np.log(np.exp(z).sum(axis=-1, keepdims=True))   # log-sum-exp trick

def cross_entropy_from_logits(z, y_idx):
    ls = log_softmax(z)
    return -ls[np.arange(len(y_idx)), y_idx].mean()

def naive_softmax(z):
    e = np.exp(z)
    return e / e.sum(axis=-1, keepdims=True)

