def char_ngrams(word, n_min=3, n_max=6):
    """fastText-style subwords: n-grams of '<word>' for n_min..n_max (by code point),
    plus the whole marked word '<word>' itself as one extra unit."""
    marked = "<" + word + ">"
    grams = []
    for n in range(n_min, n_max + 1):
        for i in range(len(marked) - n + 1):
            grams.append(marked[i:i + n])
    if marked not in grams:
        grams.append(marked)
    return grams

def fnv1a_32(text):
    h = 2166136261
    for byte in text.encode("utf-8"):
        h = ((h ^ byte) * 16777619) & 0xFFFFFFFF
    return h

def ngram_buckets(word, n_min=3, n_max=6, num_buckets=2_000_000):
    """Bucket id for every subword unit of `word` (collisions are possible and accepted)."""
    return [fnv1a_32(g) % num_buckets for g in char_ngrams(word, n_min, n_max)]

def word_vector(word, table, n_min=3, n_max=6):
    """Mean of the bucket embeddings; table has shape (num_buckets, dim)."""
    ids = ngram_buckets(word, n_min, n_max, table.shape[0])
    return sum(table[i] for i in ids) / len(ids)

