import numpy as np


def make_schedule(T=1000, beta_start=1e-4, beta_end=0.02):
    betas = np.linspace(beta_start, beta_end, T)
    alphas = 1.0 - betas
    alpha_bar = np.cumprod(alphas)            # alpha_bar[t] = prod_{s<=t} (1 - beta_s), 0-based t
    return betas, alpha_bar


def q_sample(x0, t, alpha_bar, rng):
    """Draw x_t ~ q(x_t | x_0) = N(sqrt(ab_t) x0, (1 - ab_t) I) in one shot. Returns (x_t, eps)."""
    eps = rng.standard_normal(x0.shape)
    ab = alpha_bar[t]
    return np.sqrt(ab) * x0 + np.sqrt(1.0 - ab) * eps, eps


def predict_x0(x_t, t, eps_hat, alpha_bar):
    """Invert the closed form given a noise prediction."""
    ab = alpha_bar[t]
    return (x_t - np.sqrt(1.0 - ab) * eps_hat) / np.sqrt(ab)


def eps_loss(eps, eps_hat):
    """Training objective for epsilon-prediction: plain MSE between true and predicted noise."""
    return float(np.mean((eps - eps_hat) ** 2))

