from collections import deque
from itertools import islice

def batched(iterable, n):
    if n < 1:
        raise ValueError("n must be at least 1")
    def gen():
        it = iter(iterable)
        while True:
            batch = tuple(islice(it, n))
            if not batch:
                return
            yield batch
    return gen()

def sliding_window(iterable, n):
    if n < 1:
        raise ValueError("n must be at least 1")
    def gen():
        it = iter(iterable)
        window = deque(islice(it, n), maxlen=n)
        if len(window) < n:
            return
        yield tuple(window)
        for item in it:
            window.append(item)
            yield tuple(window)
    return gen()

