import functools
import time

def retry(times, delay=0.0, backoff=2.0, exceptions=(Exception,), sleep=time.sleep):
    if times < 1:
        raise ValueError("times must be >= 1")
    exceptions = tuple(exceptions)

    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            for attempt in range(times):
                try:
                    return func(*args, **kwargs)
                except exceptions:
                    if attempt == times - 1:
                        raise
                    sleep(delay * backoff ** attempt)
        return wrapper
    return decorator

