import math, random

p = [0.200, 0.021, 0.001, 0.600, 0.022, 0.008, 0.900, 0.029, 0.400, 0.0045]
assert bonferroni(p) == [False, False, True, False, False, False, False, False, False, True]
# BH: sorted p = .001 .0045 .008 .021 .022 .029 ...; thresholds .005 .010 .015 .020 .025 .030 ...
# rank 4 (.021) misses its own threshold (.020) but rank 5 and 6 pass, so ranks 1-6 are all rejected
assert benjamini_hochberg(p) == [False, True, True, False, True, True, False, True, False, True]
assert sum(benjamini_hochberg(p)) == 6 and sum(bonferroni(p)) == 2

assert bonferroni([]) == [] and benjamini_hochberg([]) == []
assert benjamini_hochberg([0.04]) == [True] and benjamini_hochberg([0.06]) == [False]
assert benjamini_hochberg([0.5, 0.6, 0.7]) == [False] * 3
assert benjamini_hochberg([0.01, 0.02, 0.03]) == [True] * 3

# 20 independent tests at alpha = 0.05
assert abs(20 * 0.05 - 1.0) < 1e-12
assert abs((1 - 0.95 ** 20) - 0.6415140775914581) < 1e-12

# BH always rejects at least everything Bonferroni rejects
r = random.Random(0)
for _ in range(500):
    ps = [round(r.random() ** 3, 4) for _ in range(r.randint(1, 25))]
    b, h = bonferroni(ps), benjamini_hochberg(ps)
    assert all(hh or not bb for bb, hh in zip(b, h))
    # rejected set is closed downwards: a rejected p implies every smaller p is rejected
    if any(h):
        cutoff = max(q for q, hh in zip(ps, h) if hh)
        assert all(hh for q, hh in zip(ps, h) if q <= cutoff)

# invalid input is rejected instead of silently counted as significant
nan = float("nan")
for fn in (bonferroni, benjamini_hochberg):
    for bad in ([nan, 0.001], [0.01, -0.1], [1.2, 0.5], [0.01, None]):
        try:
            fn(bad)
        except (ValueError, TypeError):
            pass
        else:
            raise AssertionError((fn.__name__, bad))
for bad_level in (0, -0.05, 1.5, nan):
    for fn in (bonferroni, benjamini_hochberg):
        try:
            fn([0.01, 0.02], bad_level)
        except ValueError:
            pass
        else:
            raise AssertionError((fn.__name__, bad_level))

# boundary p-values 0 and 1 are valid; with q = 1 BH rejects everything
assert benjamini_hochberg([0.0, 1.0], q=0.05) == [True, False]
assert benjamini_hochberg([0.3, 1.0], q=1) == [True, True]
assert bonferroni([0.0, 1.0]) == [True, False]

