def run(kind):
    log = []

    def f():
        try:
            log.append("try")
            if kind == "raise":
                raise ValueError("bad")
            if kind == "return":
                return "from try"
        except ValueError:
            log.append("except")
            return "from except"
        else:
            log.append("else")
            return "from else"
        finally:
            log.append("finally")

