class ConfigError(Exception):
    """Base class: callers can catch this to handle any error from the library."""


class ConfigValueError(ConfigError):
    pass


class ConfigFileError(ConfigError):
    """The config file is missing or unreadable."""
    pass


def parse_port(text):
    try:
        value = int(text)
    except ValueError as exc:
        raise ConfigValueError(f"port must be an integer, got {text!r}") from exc
    if not 0 < value < 65536:
        raise ConfigValueError(f"port out of range: {value}")
    return value


def read_port(path):
    try:
        with open(path, encoding="utf-8") as fh:
            text = fh.read().strip()
    except OSError as exc:
        raise ConfigFileError(f"cannot read {path!r}") from exc
    return parse_port(text)


def implicit_chain():
    try:
        int("x")
    except ValueError:
        raise ConfigValueError("raised without 'from'")


def suppressed_chain():
    try:
        int("x")
    except ValueError:
        raise ConfigValueError("raised 'from None'") from None

